# CONFIG -- edit these to change the run
# ============================================================
ENTRY_MODE = "engulfing"      # "indicator" or "engulfing"
INITIAL_CAPITAL = 1000.0
WINDOW_DAYS = 30              # trading days to backtest (uses the most recent N)
STOP_LOSS_PCT = 0.02
TAKE_PROFIT_PCT = 0.05
BUY_THRESHOLD = 3.5
SELL_THRESHOLD = 2.5
MAX_POSITION_PCT = 0.05
ENGULFING_BODY_RATIO = 1.0
ENGULFING_USE_VOLUME_CONFIRMATION = False   # gold spot has no real volume feed
ENGULFING_USE_SMA_CONFIRMATION = True
