# ============================================================
# INDICATORS (pure Python, no numpy)
# ============================================================

def calculate_rsi(prices, period=14):
    if len(prices) < period + 1:
        return 50.0
    deltas = [prices[i] - prices[i-1] for i in range(len(prices)-period, len(prices))]
    gains = [d for d in deltas if d > 0]
    losses = [-d for d in deltas if d < 0]
    avg_gain = sum(gains) / period
    avg_loss = sum(losses) / period
    if avg_loss == 0:
        return 100.0 if avg_gain > 0 else 50.0
    rs = avg_gain / avg_loss
    return 100 - (100 / (1 + rs))


def calculate_macd(prices, fast=12, slow=26, signal=9):
    if len(prices) < slow:
        return 0.0, 0.0, 0.0
    ema_fast = sum(prices[-fast:]) / fast
    ema_slow = sum(prices[-slow:]) / slow
    macd = ema_fast - ema_slow
    signal_line = macd  # simplified (single-point) signal line, same as the full system
    return macd, signal_line, macd - signal_line


def calculate_sma(prices, period=20):
    if len(prices) < period:
        return sum(prices) / len(prices)
    return sum(prices[-period:]) / period


def calculate_momentum(prices, period=10):
    if len(prices) < period:
        return 0.0
    return (prices[-1] - prices[-period]) / prices[-period] * 100


# ============================================================
# ENGULFING PATTERN DETECTION (resolution-agnostic: works on
# whatever bars it's given, here real 1-hour bars)
# ============================================================

def is_regular_hours(ts_ms):
    dt = datetime.fromtimestamp(ts_ms / 1000, tz=timezone.utc)
    et_hour = (dt.hour - 4) % 24  # EDT approx (UTC-4)
    if et_hour < 9 or (et_hour == 9 and dt.minute < 30) or et_hour >= 16:
        return False
    return True


def detect_engulfing_patterns(bars, body_ratio_min=1.0, sma_period=20,
                               use_volume_confirmation=True, use_sma_confirmation=True,
                               regular_hours_only=True):
    results = []
    if len(bars) < sma_period + 2:
        return results

    for i in range(sma_period, len(bars)):
        prev, curr = bars[i - 1], bars[i]

        if regular_hours_only and not is_regular_hours(curr['t']):
            continue

        prev_body = abs(prev['c'] - prev['o'])
        curr_body = abs(curr['c'] - curr['o'])
        if prev_body == 0:
            continue

        is_bullish = (prev['c'] < prev['o'] and curr['c'] > curr['o']
                      and curr['o'] <= prev['c'] and curr['c'] >= prev['o']
                      and curr_body >= prev_body * body_ratio_min)
        is_bearish = (prev['c'] > prev['o'] and curr['c'] < curr['o']
                      and curr['o'] >= prev['c'] and curr['c'] <= prev['o']
                      and curr_body >= prev_body * body_ratio_min)
        if not (is_bullish or is_bearish):
            continue

        window = bars[i - sma_period:i]
        sma = sum(b['c'] for b in window) / sma_period
        pattern = 'bullish_engulfing' if is_bullish else 'bearish_engulfing'

        sma_ok = True
        if use_sma_confirmation:
            sma_ok = curr['c'] >= sma if pattern == 'bullish_engulfing' else curr['c'] <= sma

        vol_ok = True
        if use_volume_confirmation:
            avg_vol = sum(b['v'] for b in window) / sma_period
            vol_ok = avg_vol > 0 and curr['v'] >= 1.2 * avg_vol

        confidence = 0.5 + (0.25 if vol_ok else 0) + (0.25 if sma_ok else 0)
        results.append({
            'timestamp': curr['t'],
            'date': datetime.fromtimestamp(curr['t'] / 1000, tz=timezone.utc).strftime('%Y-%m-%d'),
            'pattern_type': pattern,
            'confidence': confidence,
        })
    return results


# Precompute: collapse to the single highest-confidence pattern per calendar
# day (the backtest fills at that day's daily close, so "did a confirmed
# pattern occur today" is the right granularity -- not a sub-day queue).
_raw_patterns = detect_engulfing_patterns(
    HOURLY_BARS,
    body_ratio_min=ENGULFING_BODY_RATIO,
    use_volume_confirmation=ENGULFING_USE_VOLUME_CONFIRMATION,
    use_sma_confirmation=ENGULFING_USE_SMA_CONFIRMATION,
    regular_hours_only=ENGULFING_REGULAR_HOURS_ONLY,
)
PATTERNS_BY_DATE = {}
for p in _raw_patterns:
    existing = PATTERNS_BY_DATE.get(p['date'])
    if existing is None or p['confidence'] > existing['confidence']:
        PATTERNS_BY_DATE[p['date']] = p


# ============================================================
# MACRO AGENT -- pure local calendar math, genuinely real, no
# network needed (same FOMC-proximity logic as the full system)
# ============================================================

FOMC_DATES_2026 = [
    "2026-01-28", "2026-03-18", "2026-04-29", "2026-06-17",
    "2026-07-29", "2026-09-16", "2026-10-28", "2026-12-09",
]

def days_until_next_fomc(as_of_date_str):
    as_of = datetime.strptime(as_of_date_str, "%Y-%m-%d")
    upcoming = [datetime.strptime(d, "%Y-%m-%d") for d in FOMC_DATES_2026]
    future = [d for d in upcoming if d >= as_of]
    if not future:
        return 999
    return (min(future) - as_of).days


def macro_agent(as_of_date_str):
    days = days_until_next_fomc(as_of_date_str)
    dampen_factor = 1.0
    suppress_buy = False
    if days <= 1:
        suppress_buy = True
    elif days <= 3:
        dampen_factor *= 0.85
    return {
        'rating': 1 if suppress_buy else 3,
        'dampen_factor': dampen_factor,
        'suppress_buy': suppress_buy,
        'confidence': 0.8,
        'data_source': 'local_calendar_only',
        'agent_role': 'dampener',
        'name': 'Macro Agent',
    }


def degraded_agent(name):
    """No API key / network in this standalone script -- honest neutral,
    never fabricated, exactly like the full system's degraded-mode path."""
    return {
        'rating': 3, 'confidence': 0.0, 'data_source': 'degraded_no_data',
        'agent_role': 'other', 'name': name,
    }


# ============================================================
# TECHNICAL ANALYST (the only agent with real market data here)
# ============================================================

def technical_analyst(trailing_prices, current_date_str):
    if ENTRY_MODE == 'engulfing':
        pattern = PATTERNS_BY_DATE.get(current_date_str)
        if pattern:
            conf = pattern['confidence']
            if pattern['pattern_type'] == 'bullish_engulfing':
                rating = 5 if conf > 0.7 else 4 if conf > 0.5 else 3
            else:
                rating = 1 if conf > 0.7 else 2 if conf > 0.5 else 3
            return {'rating': rating, 'confidence': conf, 'data_source': 'real_embedded_data',
                    'agent_role': 'technical', 'name': 'Technical Analyst',
                    'pattern_type': pattern['pattern_type']}
        return {'rating': 3, 'confidence': 0.0, 'data_source': 'real_embedded_data_no_pattern_today',
                'agent_role': 'technical', 'name': 'Technical Analyst', 'pattern_type': 'none'}

    # indicator mode
    if not trailing_prices:
        return {'rating': 3, 'confidence': 0.0, 'data_source': 'real_embedded_data',
                'agent_role': 'technical', 'name': 'Technical Analyst'}
    rsi = calculate_rsi(trailing_prices)
    macd, signal, hist = calculate_macd(trailing_prices)
    momentum = calculate_momentum(trailing_prices)
    if rsi > 65 and momentum > 0 and hist > 0:
        rating = 5
    elif rsi > 55 and momentum > 0:
        rating = 4
    elif rsi < 35 and momentum < 0:
        rating = 2
    elif rsi > 80:
        rating = 1
    else:
        rating = 3
    return {'rating': rating, 'confidence': abs((rsi - 50) / 50), 'data_source': 'real_embedded_data',
            'agent_role': 'technical', 'name': 'Technical Analyst', 'rsi': rsi}


# ============================================================
# PORTFOLIO MANAGER -- weighted aggregation (Technical = 50%,
# other averaged agents share the other 50%), dampener + crisis
# override, same thresholds as the full system
# ============================================================

def portfolio_manager(analyses):
    dampeners = [a for a in analyses if a.get('agent_role') == 'dampener']
    non_dampeners = [a for a in analyses if a.get('agent_role') != 'dampener']

    technical = [a['rating'] for a in non_dampeners if a.get('agent_role') == 'technical']
    others = [a['rating'] for a in non_dampeners if a.get('agent_role') == 'other']

    if technical and others:
        weighted = 0.5 * (sum(technical) / len(technical)) + 0.5 * (sum(others) / len(others))
    elif technical:
        weighted = sum(technical) / len(technical)
    else:
        weighted = 3.0

    dampen_factor = 1.0
    suppress_buy = False
    for d in dampeners:
        dampen_factor *= d.get('dampen_factor', 1.0)
        if d.get('suppress_buy'):
            suppress_buy = True

    adjusted = weighted * dampen_factor

    if suppress_buy:
        decision = 'SELL' if adjusted <= SELL_THRESHOLD else 'HOLD'
    elif adjusted >= BUY_THRESHOLD:
        decision = 'BUY'
    elif adjusted <= SELL_THRESHOLD:
        decision = 'SELL'
    else:
        decision = 'HOLD'

    return {'decision': decision, 'avg_rating': adjusted, 'position_size': MAX_POSITION_PCT if decision == 'BUY' else 0.0}


def evaluate_day(trailing_prices, current_date_str):
    technical = technical_analyst(trailing_prices, current_date_str)
    others = [
        degraded_agent('Fundamental Analyst'),
        degraded_agent('Sentiment Analyst'),
        degraded_agent('News Analyst'),
        degraded_agent('Bull Researcher'),
        degraded_agent('Bear Researcher'),
        degraded_agent('Geopolitical Agent'),
    ]
    macro = macro_agent(current_date_str)
    return portfolio_manager([technical] + others + [macro]), technical


# ============================================================
# BACKTEST LOOP -- same exit priority as the full system:
# stop_loss / take_profit -> pattern_reversal (engulfing mode) ->
# agent_decision -> window_close
# ============================================================

def run_backtest():
    n = len(DAILY_CLOSES)
    start_idx = max(60, n - WINDOW_DAYS)  # need >=60 days trailing for indicator mode
    capital = INITIAL_CAPITAL
    position = None  # {'entry_price', 'shares', 'cost', 'entry_date'}
    trades = []

    for day_idx in range(start_idx, n):
        current_price = DAILY_CLOSES[day_idx]
        current_date = DAILY_DATES[day_idx][:10]
        trailing_prices = DAILY_CLOSES[:day_idx]

        if position is not None:
            pct_change = (current_price - position['entry_price']) / position['entry_price']
            exit_reason = None
            if pct_change <= -STOP_LOSS_PCT:
                exit_reason = 'stop_loss'
            elif pct_change >= TAKE_PROFIT_PCT:
                exit_reason = 'take_profit'
            elif ENTRY_MODE == 'engulfing':
                pattern = PATTERNS_BY_DATE.get(current_date)
                if pattern and pattern['pattern_type'] == 'bearish_engulfing':
                    exit_reason = 'pattern_reversal'

            if exit_reason:
                proceeds = position['shares'] * current_price
                profit = proceeds - position['cost']
                capital += proceeds
                trades.append({'action': 'SELL', 'date': current_date, 'price': current_price,
                                'exit_reason': exit_reason, 'profit': profit})
                position = None
                continue

        decision_info, technical = evaluate_day(trailing_prices, current_date)
        decision = decision_info['decision']

        if ENTRY_MODE == 'engulfing' and decision == 'BUY':
            pattern = PATTERNS_BY_DATE.get(current_date)
            if not pattern or pattern['pattern_type'] != 'bullish_engulfing':
                decision = 'HOLD'  # pattern is the entry gate -- no real print today, no buy

        if decision == 'BUY' and position is None:
            cost = capital * MAX_POSITION_PCT
            shares = cost / current_price
            position = {'entry_price': current_price, 'shares': shares, 'cost': cost, 'entry_date': current_date}
            capital -= cost
            trades.append({'action': 'BUY', 'date': current_date, 'price': current_price})
        elif decision == 'SELL' and position is not None:
            proceeds = position['shares'] * current_price
            profit = proceeds - position['cost']
            capital += proceeds
            trades.append({'action': 'SELL', 'date': current_date, 'price': current_price,
                            'exit_reason': 'agent_decision', 'profit': profit})
            position = None

    if position is not None:
        final_price = DAILY_CLOSES[-1]
        proceeds = position['shares'] * final_price
        profit = proceeds - position['cost']
        capital += proceeds
        trades.append({'action': 'SELL', 'date': DAILY_DATES[-1][:10], 'price': final_price,
                        'exit_reason': 'window_close', 'profit': profit})

    return capital, trades


if __name__ == "__main__":
    print("=" * 60)
    print("STANDALONE MOMENTUM/ENGULFING BACKTEST -- XAUUSD (real data)")
    print("=" * 60)
    print(f"Entry mode:      {ENTRY_MODE}")
    print(f"Window:          last {WINDOW_DAYS} real trading days ({DAILY_DATES[-WINDOW_DAYS][:10]} to {DAILY_DATES[-1][:10]})")
    print(f"Initial capital: ${INITIAL_CAPITAL:,.2f}")
    print(f"Real patterns available on {len(PATTERNS_BY_DATE)} of the embedded 700 hourly bars' calendar days")
    print()

    final_capital, trades = run_backtest()
    total_return = (final_capital - INITIAL_CAPITAL) / INITIAL_CAPITAL

    closed = [t for t in trades if t['action'] == 'SELL']
    wins = [t for t in closed if t.get('profit', 0) > 0]
    exit_reasons = {}
    for t in closed:
        r = t.get('exit_reason', 'unknown')
        exit_reasons[r] = exit_reasons.get(r, 0) + 1

    print(f"Final capital:   ${final_capital:,.2f}")
    print(f"Total return:    {total_return*100:+.2f}%")
    print(f"Closed trades:   {len(closed)}")
    if closed:
        print(f"Win rate:        {len(wins)/len(closed)*100:.1f}%")
    print(f"Exit reasons:    {exit_reasons}")
    print()
    print("Trade log:")
    for i, t in enumerate(trades, 1):
        if t['action'] == 'BUY':
            print(f"  {i:2}. BUY  {t['date']}  @ ${t['price']:,.2f}")
        else:
            print(f"  {i:2}. SELL {t['date']}  @ ${t['price']:,.2f}  "
                  f"({t.get('exit_reason')})  P&L: {t.get('profit', 0):+.3f}")
